export function installTablebases(api){
 const dialog=document.createElement('dialog');dialog.id='tablebasesDialog';dialog.className='mode-screen';dialog.setAttribute('aria-labelledby','tablebasesTitle');
 dialog.innerHTML='<div class="mode-heading"><button id="tablebasesBack"><span aria-hidden="true" class="back-chevron"></span><span>Options</span></button><h2 id="tablebasesTitle">Tablebases</h2></div><div class="benchmark-content"><h3>3–4 pieces · Included</h3><p>Installed with the app. Available offline and used automatically.</p><h3>5 pieces · Optional download <span id="tablebasesInstalledCheck" class="tablebase-check" aria-label="Installed" hidden>✓</span></h3><p>Complete Syzygy WDL + DTZ set · 980 MB.<br>Wi-Fi recommended. Requires about 1.1 GB of free storage.</p><p id="tablebasesStatus" role="status"><span id="tablebasesStatusCheck" class="tablebase-check" aria-hidden="true" hidden>✓ </span><span id="tablebasesStatusText">Checking…</span></p><progress id="tablebasesProgress" max="1" value="0"></progress><p id="tablebasesSize"></p><button class="primary" id="tablebasesDownload">Download 5-piece Tablebases</button><button id="tablebasesPause" hidden>Pause Download</button><p>Stockfish 19 automatically use the installed tablebases. The optional 5-piece set is used once its download is complete. The TB indicator appears when a search uses them.</p><p>Keep the app open while downloading. Completed files are retained if you pause or close the app.</p></div>';
 document.body.append(dialog);const $=id=>document.getElementById(id);let timer=null,busy=false;
 function setStatus(message,installed=false){$('tablebasesStatusText').textContent=message;$('tablebasesStatusCheck').hidden=!installed;}
 function render(s){setStatus(s.message,s.installed);$('tablebasesInstalledCheck').hidden=!s.installed;$('tablebasesProgress').value=s.total?s.bytes/s.total:0;$('tablebasesSize').textContent=Math.round(s.bytes/1e6)+' / '+Math.round(s.total/1e6)+' MB · '+s.files+' / '+s.fileCount+' files';$('tablebasesDownload').hidden=s.running;$('tablebasesDownload').disabled=s.installed||s.running;$('tablebasesPause').hidden=!s.running;$('tablebasesDownload').textContent=s.installed?'Installed':s.bytes?'Resume Download':'Download 5-piece Tablebases';}
 async function refresh(){if(busy)return;busy=true;try{render(await chessNative.tablebaseStatus());}catch{setStatus('Could not read download status. Please try again.');}finally{busy=false;}}
 $('tablebasesDownload').onclick=async()=>{if($('tablebasesDownload').disabled)return;try{render(await chessNative.downloadTablebases());}catch{setStatus('Could not start the download. Please try again.');}};
 $('tablebasesPause').onclick=async()=>{try{render(await chessNative.pauseTablebases());}catch{setStatus('Could not pause. Please try again.');}};
 $('tablebasesBack').onclick=()=>{dialog.close();api.open('settingsDialog');};dialog.addEventListener('close',()=>clearInterval(timer));
 return {open(){api.open('tablebasesDialog');if(!globalThis.chessNative?.tablebaseStatus){setStatus('Optional downloads are available in the iPhone app.');$('tablebasesDownload').hidden=true;return;}refresh();timer=setInterval(refresh,1000);}};
}
